package com.visualreadycheck;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

final class RaidParty
{
    final String raid;
    final int controller;
    final List<String> names;
    private int world;
    boolean localLeader;

    RaidParty(String raid, int controller, List<String> names)
    {
        this.raid = raid;
        this.controller = controller;
        this.names = Collections.unmodifiableList(new ArrayList<>(names));
    }

    String leader() { return names.get(0); }
    String key()
    {
        if (raid.equals("CoX")) { return raid + ":" + world + ":" + controller; }
        // Lobby membership is the shared identity. Do not require a controller
        // varp (or non-leader display ordering) to agree across clients.
        List<String> roster = new ArrayList<>(names);
        Collections.sort(roster);
        return raid + ":" + world + ":" + leader() + ":" + String.join(",", roster);
    }
    static String name(String value)
    {
        return value == null ? "" : Text.removeTags(value).replace('\u00a0', ' ').replace('_', ' ').trim().toLowerCase(Locale.ROOT);
    }

    static RaidParty read(Client client)
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) { return null; }
        RaidParty party = readNames(client, "ToB", VarPlayerID.TOB_MYCONTROLLER,
            VarbitID.TOB_CLIENT_PARTYSTATUS, 5, InterfaceID.TobHud.NAMES);
        if (party != null) { return party; }
        party = readNames(client, "ToA", VarPlayerID.TOA_MYCONTROLLER,
            VarbitID.TOA_CLIENT_PARTYSTATUS, 8, InterfaceID.ToaLobby.NAMES);
        if (party != null) { return party; }
        party = readNames(client, "TFA", VarPlayerID.TFA_MYCONTROLLER,
            VarbitID.TFA_CLIENT_PARTYSTATUS, 8, InterfaceID.TfaLobby.NAMES);
        if (party != null) { return party; }
        if (client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER) == -1) { return null; }
        // The server supplies these independently of the party tab. CoX's pre-start
        // assembly room is inside the instance; progress > 0 means the raid has begun.
        if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) != 1
            || client.getVarbitValue(VarbitID.RAIDS_CLIENT_PROGRESS) != 0) { return null; }
        party = validated(client, "CoX", client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER),
            Collections.singletonList(name(client.getLocalPlayer().getName())));
        if (party != null) { party.localLeader = client.getVarbitValue(VarbitID.RAIDS_CLIENT_ISLEADER) == 1; }
        return party;
    }

    private static RaidParty readNames(Client client, String raid, int controllerVar, int statusVar, int count, int lobbyWidget)
    {
        // These automatic lobby HUDs are not the manually opened party-details panel.
        Widget lobby = client.getWidget(lobbyWidget);
        if (lobby == null || lobby.isHidden()) { return null; }
        int status = client.getVarbitValue(statusVar);
        if (status != 1 && status != 2) { return null; }
        List<String> names = new ArrayList<>();
        // In-raid name varcs can still contain the previous raid's roster in the lobby.
        // The automatic lobby HUD is the current server-updated party list.
        String text = lobby.getText();
        if (text == null || text.isEmpty()) { return null; }
        String[] slots = text.split("(?i)<br\\s*/?>", -1);
        if (emptySlot(name(slots[0]))) { return null; }
        for (String slot : slots) { add(names, slot); }
        if (names.size() > count) { return null; }
        return validated(client, raid, client.getVarpValue(controllerVar), names);
    }

    private static void add(List<String> names, String raw)
    {
        String name = name(raw);
        if (!emptySlot(name) && !names.contains(name)) { names.add(name); }
    }

    private static boolean emptySlot(String name)
    {
        // The lobby draws vacant slots as a dash on some clients. It is not a player.
        return name.isEmpty() || name.equals("-");
    }

    private static RaidParty validated(Client client, String raid, int controller, List<String> names)
    {
        if (names.isEmpty() || !names.contains(name(client.getLocalPlayer().getName()))) { return null; }
        RaidParty party = new RaidParty(raid, controller, names);
        party.world = client.getWorld();
        party.localLeader = party.leader().equals(name(client.getLocalPlayer().getName()));
        return party;
    }
}

package com.visualreadycheck;

import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.Set;

/** Pure state machine; all production access is confined to the client thread. */
final class ReadyCheck
{
    final String id;
    final long leader;
    final long deadline;
    final Set<Long> members;
    final Set<Long> ready = new LinkedHashSet<>();
    private String result;
    private long finishedAt;

    ReadyCheck(String id, long leader, long deadline, Collection<Long> members)
    {
        this.id = id;
        this.leader = leader;
        this.deadline = deadline;
        this.members = new LinkedHashSet<>(members);
    }

    boolean markReady(String checkId, long sender, long now)
    {
        tick(now);
        if (result != null || !id.equals(checkId) || !members.contains(sender)) { return false; }
        boolean changed = ready.add(sender);
        if (ready.containsAll(members)) { finish("Everyone is ready!", now); }
        return changed;
    }

    void tick(long now)
    {
        if (result == null && now >= deadline) { finish("Time expired", now); }
    }

    void cancel(String reason, long now)
    {
        if (result == null) { finish(reason, now); }
    }

    private void finish(String reason, long now) { result = reason; finishedAt = now; }
    boolean active() { return result == null; }
    String result() { return result; }
    boolean visible(long now) { return active() || now - finishedAt < 8000; }
}

package com.visualreadycheck;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.util.Objects;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class ReadyOverlay extends Overlay
{
    private final VisualReadyCheckPlugin plugin;
    private volatile Rectangle button = new Rectangle();
    private volatile String renderedId;
    private Point press;
    private String pressedId;
    private volatile Point hover = new Point(-1, -1);
    private boolean captured;
    private boolean dragged;

    ReadyOverlay(VisualReadyCheckPlugin plugin)
    {
        super(plugin);
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setMovable(true);
        setResizable(true);
        setMinimumSize(186);
        setPriority(PRIORITY_HIGH);
    }

    final MouseAdapter mouse = new MouseAdapter()
    {
        @Override public MouseEvent mouseMoved(MouseEvent event)
        {
            hover = event.getPoint();
            return event;
        }

        @Override public MouseEvent mouseExited(MouseEvent event)
        {
            hover = new Point(-1, -1);
            return event;
        }

        @Override public MouseEvent mousePressed(MouseEvent event)
        {
            captured = false;
            if (!event.isConsumed() && event.getButton() == MouseEvent.BUTTON1 && !event.isAltDown()
                && plugin.view().visible && plugin.view().canReady && button.contains(event.getPoint()))
            {
                press = event.getPoint();
                pressedId = renderedId;
                captured = true;
                dragged = false;
                event.consume();
            }
            return event;
        }

        @Override public MouseEvent mouseDragged(MouseEvent event)
        {
            if (captured)
            {
                if (event.isAltDown() || press.distance(event.getPoint()) > 4) { dragged = true; }
                event.consume();
            }
            return event;
        }

        @Override public MouseEvent mouseReleased(MouseEvent event)
        {
            if (captured && event.getButton() == MouseEvent.BUTTON1)
            {
                captured = false;
                if (!dragged && !event.isAltDown() && press.distance(event.getPoint()) <= 4
                    && button.contains(event.getPoint()) && Objects.equals(pressedId, renderedId))
                {
                    plugin.ready(pressedId);
                }
                event.consume();
            }
            return event;
        }

        @Override public MouseEvent mouseClicked(MouseEvent event)
        {
            if (!event.isAltDown() && plugin.view().visible && button.contains(event.getPoint())) { event.consume(); }
            return event;
        }
    };

    @Override public Dimension render(Graphics2D graphics)
    {
        ReadyView view = plugin.view();
        if (!view.visible && !plugin.preview)
        {
            button = new Rectangle();
            renderedId = null;
            return null;
        }
        VisualReadyCheckConfig colors = plugin.config();
        double scale = Math.max(75, Math.min(200, colors.overlayScale())) / 100.0;
        // RuneLite persists the dragged width. Derive a uniform scale from it so
        // adding party rows grows the card instead of shrinking its text.
        Dimension preferred = getPreferredSize();
        if (preferred != null)
        {
            scale = Math.max(0.75, Math.min(2.0, preferred.width / 248.0));
        }
        boolean preview = !view.visible;
        java.util.List<String> rows = preview
            ? java.util.Arrays.asList("READY   Teammate", "WAITING You") : view.rows;
        int count = Math.min(8, rows.size());
        int width = 248;
        int extra = rows.size() > count ? 18 : 0;
        int buttonY = 64 + count * 24 + extra + 8;
        int height = buttonY + 32 + 12 + (preview ? 18 : 0);
        long ready = rows.stream().filter(row -> row.startsWith("READY")).count();
        boolean active = preview || view.active;
        boolean actionable = preview || view.canReady;
        Rectangle bounds = getBounds();
        Rectangle target = new Rectangle(bounds.x + (int) Math.ceil(14 * scale),
            bounds.y + (int) Math.ceil(buttonY * scale),
            (int) Math.floor((width - 14) * scale) - (int) Math.ceil(14 * scale),
            (int) Math.floor((buttonY + 32) * scale) - (int) Math.ceil(buttonY * scale));
        Graphics2D g = (Graphics2D) graphics.create();
        g.scale(scale, scale);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        // Read the profile-backed colors each frame so the preview updates immediately.
        g.setColor(new Color(0, 0, 0, 65));
        g.fillRoundRect(2, 3, width - 4, height - 3, 12, 12);
        g.setColor(colors.background());
        g.fillRoundRect(0, 0, width - 1, height - 4, 10, 10);
        g.setColor(colors.border());
        g.drawRoundRect(0, 0, width - 1, height - 4, 10, 10);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 14));
        g.setColor(colors.text());
        g.drawString(active ? "Ready check" : "Check complete", 14, 25);
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
        g.setColor(colors.secondaryText());
        String subtitle = active ? ready + " of " + rows.size() + " ready" : view.status;
        g.drawString(fit(g, subtitle, width - 28), 14, 43);

        String timer = preview ? "30s" : countdown(view.status);
        if (active && !timer.isEmpty())
        {
            g.setColor(blend(colors.background(), colors.timer(), 0.16));
            g.fillRoundRect(width - 62, 13, 48, 29, 8, 8);
            g.setColor(colors.timer());
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
            g.drawString(timer, width - 38 - g.getFontMetrics().stringWidth(timer) / 2, 33);
        }
        g.setColor(blend(colors.background(), colors.border(), 0.6));
        g.drawLine(14, 55, width - 15, 55);
        for (int i = 0; i < count; i++)
        {
            String row = rows.get(i);
            boolean isReady = row.startsWith("READY");
            int split = row.indexOf(' ');
            String name = split < 0 ? row : row.substring(split).trim();
            int y = 79 + 24 * i;
            g.setColor(isReady ? colors.ready() : colors.waiting());
            if (isReady)
            {
                g.setStroke(new java.awt.BasicStroke(1.7f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));
                g.drawLine(15, y - 5, 18, y - 2);
                g.drawLine(18, y - 2, 24, y - 9);
            }
            else { g.drawOval(16, y - 9, 7, 7); }
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
            g.setColor(colors.text());
            g.drawString(fit(g, name, 130), 33, y);
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
            g.setColor(isReady ? colors.ready() : colors.waiting());
            String state = isReady ? "Ready" : active ? "Waiting" : "Not ready";
            g.drawString(state, width - 14 - g.getFontMetrics().stringWidth(state), y);
        }
        if (extra > 0)
        {
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
            g.setColor(colors.secondaryText());
            g.drawString("+" + (rows.size() - count) + " more in the side panel", 14, buttonY - 9);
        }
        boolean hovered = view.canReady && target.contains(hover);
        Color fill = actionable ? (hovered ? blend(colors.button(), Color.WHITE, 0.15) : colors.button())
            : blend(colors.background(), colors.ready(), 0.15);
        g.setColor(fill);
        g.fillRoundRect(14, buttonY, width - 28, 32, 6, 6);
        g.setColor(actionable ? contrast(fill) : colors.ready());
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        String label = actionable ? "I'm ready" : active ? "You're ready" : "Check finished";
        g.drawString(label, (width - g.getFontMetrics().stringWidth(label)) / 2, buttonY + 21);
        if (preview)
        {
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 9));
            g.setColor(colors.secondaryText());
            String hint = "Alt + drag: move / corners: resize";
            g.drawString(hint, (width - g.getFontMetrics().stringWidth(hint)) / 2, height - 13);
        }
        g.dispose();
        renderedId = view.canReady ? view.id : null;
        button = view.canReady ? target : new Rectangle();
        return new Dimension((int) Math.ceil(width * scale), (int) Math.ceil(height * scale));
    }

    private static Color blend(Color base, Color tint, double amount)
    {
        return new Color((int) (base.getRed() * (1 - amount) + tint.getRed() * amount),
            (int) (base.getGreen() * (1 - amount) + tint.getGreen() * amount),
            (int) (base.getBlue() * (1 - amount) + tint.getBlue() * amount));
    }

    private static Color contrast(Color background)
    {
        double luminance = 0.2126 * linear(background.getRed())
            + 0.7152 * linear(background.getGreen()) + 0.0722 * linear(background.getBlue());
        return luminance > 0.179 ? Color.BLACK : Color.WHITE;
    }

    private static double linear(int channel)
    {
        double value = channel / 255.0;
        return value <= 0.04045 ? value / 12.92 : Math.pow((value + 0.055) / 1.055, 2.4);
    }

    private static String countdown(String status)
    {
        java.util.regex.Matcher match = java.util.regex.Pattern.compile("(\\d+)s remaining").matcher(status);
        return match.find() ? match.group(1) + "s" : "";
    }

    private static String fit(Graphics2D g, String text, int width)
    {
        if (g.getFontMetrics().stringWidth(text) <= width) { return text; }
        while (!text.isEmpty() && g.getFontMetrics().stringWidth(text + "...") > width)
        {
            text = text.substring(0, text.length() - 1);
        }
        return text + "...";
    }
}

package com.visualreadycheck;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JTextArea;
import javax.swing.SpinnerNumberModel;
import javax.swing.plaf.basic.BasicButtonUI;
import net.runelite.client.ui.PluginPanel;

final class ReadyPanel extends PluginPanel
{
    private static final Color CARD = new Color(35, 38, 42);
    private static final Color TEXT = new Color(229, 232, 231);
    private static final Color MUTED = new Color(151, 158, 162);
    private static final Color ACCENT = new Color(76, 209, 173);
    private final JTextArea status = paragraph("Join a raid lobby to get started.");
    private final JLabel role = label("LOBBY ONLY", 10, MUTED, true);
    private final JLabel count = label("0 included", 10, MUTED, false);
    private final JPanel roster = new JPanel(new GridLayout(0, 1, 0, 4));
    private final JButton start = button("Start ready check", true);
    private final JButton cancel = button("Cancel check", false);
    private final JSpinner duration = new JSpinner(new SpinnerNumberModel(30, 5, 300, 5));
    private List<String> lastRows = null;

    ReadyPanel(VisualReadyCheckPlugin plugin)
    {
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(16, 10, 12, 10));
        JPanel content = stack();
        JPanel heading = stack();
        heading.add(label("Visual Ready Check", 17, TEXT, true));
        heading.add(Box.createVerticalStrut(5));
        heading.add(label("A quick check. A ready party.", 11, MUTED, false));
        content.add(heading);
        content.add(Box.createVerticalStrut(16));

        JPanel check = new JPanel(new java.awt.GridBagLayout());
        check.setOpaque(false);
        addRow(check, role, 0, 0);
        addRow(check, status, 1, 7);
        JPanel timer = new JPanel(new BorderLayout(8, 0));
        timer.setOpaque(false);
        JPanel timerLabel = stack();
        timerLabel.add(label("Duration", 12, TEXT, true));
        timerLabel.add(label("5-300 seconds", 10, MUTED, false));
        timer.add(timerLabel, BorderLayout.CENTER);
        duration.setPreferredSize(new Dimension(72, 30));
        duration.setToolTipText("Time each participant has to click ready");
        JSpinner.NumberEditor editor = new JSpinner.NumberEditor(duration, "0");
        duration.setEditor(editor);
        editor.getTextField().setColumns(3);
        editor.getTextField().setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
        timer.add(duration, BorderLayout.EAST);
        addRow(check, timer, 2, 14);
        addRow(check, start, 3, 12);
        addRow(check, cancel, 4, 6);
        content.add(card(check));
        content.add(Box.createVerticalStrut(12));

        JPanel team = stack();
        JPanel teamHeading = new JPanel(new BorderLayout());
        teamHeading.setOpaque(false);
        teamHeading.setAlignmentX(LEFT_ALIGNMENT);
        teamHeading.add(label("Party", 12, TEXT, true), BorderLayout.WEST);
        teamHeading.add(count, BorderLayout.EAST);
        team.add(teamHeading);
        team.add(Box.createVerticalStrut(9));
        roster.setOpaque(false);
        roster.setAlignmentX(LEFT_ALIGNMENT);
        team.add(roster);
        content.add(card(team));
        content.add(Box.createVerticalStrut(12));

        JPanel appearance = stack();
        appearance.add(label("Your overlay", 12, TEXT, true));
        appearance.add(Box.createVerticalStrut(8));
        JCheckBox preview = new JCheckBox("Preview overlay");
        preview.setOpaque(false);
        preview.setForeground(TEXT);
        preview.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
        preview.setAlignmentX(LEFT_ALIGNMENT);
        preview.addActionListener(e -> plugin.preview = preview.isSelected());
        appearance.add(preview);
        appearance.add(Box.createVerticalStrut(8));
        appearance.add(paragraph("Hold Alt: drag to move, or drag a corner to resize. Colors are in plugin settings."));
        content.add(card(appearance));
        content.add(Box.createVerticalStrut(12));
        content.add(paragraph("Everyone included must click the on-screen ready button, including the leader."));
        // Keep the entire stack at its preferred height instead of stretching every control.
        add(content, BorderLayout.NORTH);
        start.setEnabled(false);
        cancel.setVisible(false);
        duration.setEnabled(false);
        rebuildRoster(Collections.emptyList());
        start.addActionListener(e -> {
            try { duration.commitEdit(); }
            catch (java.text.ParseException ex) { return; }
            plugin.start((Integer) duration.getValue());
        });
        cancel.addActionListener(e -> plugin.cancel());
    }

    private static void addRow(JPanel panel, java.awt.Component component, int row, int gap)
    {
        java.awt.GridBagConstraints constraints = new java.awt.GridBagConstraints();
        constraints.gridx = 0;
        constraints.gridy = row;
        constraints.weightx = 1;
        constraints.fill = java.awt.GridBagConstraints.HORIZONTAL;
        constraints.anchor = java.awt.GridBagConstraints.WEST;
        constraints.insets = new java.awt.Insets(gap, 0, 0, 0);
        panel.add(component, constraints);
    }

    private static JPanel stack()
    {
        JPanel panel = new JPanel();
        panel.setOpaque(false);
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setAlignmentX(LEFT_ALIGNMENT);
        return panel;
    }

    private static JPanel card(JPanel contents)
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(CARD);
        panel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(51, 56, 60)),
            BorderFactory.createEmptyBorder(12, 10, 12, 10)));
        panel.setAlignmentX(LEFT_ALIGNMENT);
        panel.add(contents, BorderLayout.CENTER);
        return panel;
    }

    private static JLabel label(String text, int size, Color color, boolean bold)
    {
        JLabel label = new JLabel(text);
        label.setFont(new Font(Font.SANS_SERIF, bold ? Font.BOLD : Font.PLAIN, size));
        label.setForeground(color);
        label.setAlignmentX(LEFT_ALIGNMENT);
        return label;
    }

    private static JTextArea paragraph(String text)
    {
        JTextArea area = new JTextArea(text, 0, 16);
        area.setEditable(false);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setOpaque(false);
        area.setForeground(MUTED);
        area.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
        area.setAlignmentX(LEFT_ALIGNMENT);
        return area;
    }

    private static JButton button(String text, boolean primary)
    {
        JButton button = new JButton(text);
        button.setUI(new BasicButtonUI());
        button.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        button.setBackground(primary ? ACCENT : new Color(47, 51, 55));
        button.setForeground(primary ? new Color(18, 36, 29) : TEXT);
        button.setBorder(BorderFactory.createEmptyBorder(9, 8, 9, 8));
        button.setPreferredSize(new Dimension(180, 34));
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
        button.setAlignmentX(LEFT_ALIGNMENT);
        return button;
    }

    void update(ReadyView view, boolean leader)
    {
        String description = view.status.replace(" plugin participant(s)", " using plugin")
            .replace(" - leader: ", "\nLeader: ").replace(" - you lead", "\nYou are the leader")
            .replace(" - waiting for raid leader", "\nWaiting for the raid leader");
        if (!status.getText().equals(description)) { status.setText(description); }
        role.setText(view.active ? "CHECK IN PROGRESS" : leader ? "PARTY LEADER" : "LOBBY ONLY");
        role.setForeground(leader || view.active ? ACCENT : MUTED);
        start.setEnabled(view.canStart);
        start.setBackground(view.canStart ? ACCENT : new Color(48, 58, 56));
        start.setToolTipText(view.canStart ? "Ask included party members to ready up" : view.status);
        duration.setEnabled(leader && !view.active);
        cancel.setVisible(leader && view.active);
        cancel.setEnabled(leader && view.active);
        if (!view.rows.equals(lastRows)) { rebuildRoster(view.rows); }
        revalidate();
        repaint();
    }

    private void rebuildRoster(List<String> rows)
    {
        lastRows = new ArrayList<>(rows);
        roster.removeAll();
        int included = 0;
        for (String row : rows)
        {
            int split = row.indexOf(' ');
            String state = split < 0 ? row : row.substring(0, split);
            String name = split < 0 ? row : row.substring(split).trim();
            boolean skipped = state.equals("SKIPPED");
            if (!skipped) { included++; }
            String badge = state.equals("INCLUDED") ? "Included" : state.equals("READY") ? "Ready"
                : state.equals("WAITING") ? "Waiting" : skipped ? "Skipped" : "Not ready";
            Color color = state.equals("READY") || state.equals("INCLUDED") ? ACCENT
                : skipped ? MUTED : new Color(222, 187, 124);
            JPanel entry = new JPanel(new BorderLayout(6, 0));
            entry.setBackground(new Color(29, 32, 35));
            entry.setBorder(BorderFactory.createEmptyBorder(7, 7, 7, 7));
            JLabel player = label(name, 11, skipped ? MUTED : TEXT, false);
            player.setToolTipText(name);
            // Let Swing clip long names rather than expanding the sidebar width.
            player.setMinimumSize(new Dimension(0, 14));
            player.setPreferredSize(new Dimension(90, 14));
            entry.add(player, BorderLayout.CENTER);
            entry.add(label(badge, 10, color, false), BorderLayout.EAST);
            roster.add(entry);
        }
        count.setText(included + " included");
        if (rows.isEmpty()) { roster.add(paragraph("Your lobby party will appear here.")); }
    }
}

