package com.visualreadycheck;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import com.google.inject.Provides;
import net.runelite.client.config.ConfigManager;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.input.MouseManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.party.PartyPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Visual Ready Check", internalName = "visual-ready-check",
    description = "Clickable, timed ready checks for in-game raid parties", tags = {"raid", "party", "ready", "tob", "toa", "cox", "tfa"})
@PluginDependency(PartyPlugin.class)
public class VisualReadyCheckPlugin extends Plugin
{
    private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(VisualReadyCheckPlugin.class);
    private final Map<Long, String> peerDiagnostics = new LinkedHashMap<>();
    @Inject private VisualReadyCheckConfig config = new VisualReadyCheckConfig() {};

    @Provides
    VisualReadyCheckConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(VisualReadyCheckConfig.class);
    }

    VisualReadyCheckConfig config() { return config; }

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private PartyService partyService;
    @Inject private WSClient wsClient;
    @Inject private OverlayManager overlayManager;
    @Inject private MouseManager mouseManager;
    @Inject private ClientToolbar toolbar;

    private ReadyOverlay overlay;
    private ReadyPanel panel;
    private NavigationButton navigation;
    private volatile boolean running;
    volatile boolean preview;
    private volatile ReadyView view = ReadyView.empty();
    private RaidParty raid;
    private ReadyCheck check;
    private String checkRaidKey;
    private final Map<Long, String> checkNames = new LinkedHashMap<>();
    private final Set<String> seen = new LinkedHashSet<>();
    private long nextRefresh;
    private long lastStart;
    private long nextPresence;
    private String announcedKey;
    private final Map<Long, Presence> peers = new LinkedHashMap<>();

    private static final class Presence
    {
        final String key;
        final boolean leader;
        final long expires;
        Presence(String key, boolean leader, long now)
        {
            this.key = key;
            this.leader = leader;
            this.expires = now + 12000;
        }
    }

    @Override protected void startUp() throws Exception
    {
        running = true;
        wsClient.registerMessage(VisualReadyCheckMessage.class);
        overlay = new ReadyOverlay(this);
        overlayManager.add(overlay);
        mouseManager.registerMouseListener(overlay.mouse);
        Runnable createPanel = () -> {
            panel = new ReadyPanel(this);
            BufferedImage icon = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = icon.createGraphics();
            g.setColor(new Color(68, 205, 153));
            g.fillRoundRect(2, 2, 20, 20, 6, 6);
            g.setColor(Color.BLACK);
            g.drawLine(6, 12, 10, 16);
            g.drawLine(10, 16, 18, 7);
            g.dispose();
            navigation = NavigationButton.builder().tooltip("Visual Ready Check").icon(icon).priority(7).panel(panel).build();
            toolbar.addNavigation(navigation);
        };
        // RuneLite starts and reloads plugins on the EDT. Only dispatch and wait
        // when a caller is actually on another thread.
        if (SwingUtilities.isEventDispatchThread()) { createPanel.run(); }
        else { SwingUtilities.invokeAndWait(createPanel); }
    }

    @Override protected void shutDown()
    {
        if (partyService.isInParty()) { partyService.send(message("BYE", null)); }
        running = false;
        wsClient.unregisterMessage(VisualReadyCheckMessage.class);
        mouseManager.unregisterMouseListener(overlay.mouse);
        overlayManager.remove(overlay);
        toolbar.removeNavigation(navigation);
        check = null;
        raid = null;
        seen.clear();
        peers.clear();
        peerDiagnostics.clear();
        announcedKey = null;
        nextPresence = 0;
        checkNames.clear();
        view = ReadyView.empty();
    }

    ReadyView view() { return view; }

    @Subscribe public void onPartyChanged(PartyChanged event)
    {
        clientThread.invokeLater(() -> {
            check = null;
            seen.clear();
            peers.clear();
            peerDiagnostics.clear();
            announcedKey = null;
            nextPresence = 0;
            checkNames.clear();
            lastStart = 0;
            refresh();

        });
    }

    @Subscribe public void onClientTick(ClientTick event)
    {
        if (System.currentTimeMillis() >= nextRefresh)
        {
            nextRefresh = System.currentTimeMillis() + 200;
            refresh();
            String key = raid == null ? null : raid.key();
            if (partyService.isInParty() && localId() != -1
                && (System.currentTimeMillis() >= nextPresence || !java.util.Objects.equals(key, announcedKey)))
            {
                nextPresence = System.currentTimeMillis() + 3000;
                announcedKey = key;
                partyService.send(message("PRESENCE", null));
            }
        }
    }

    private Map<Long, String> connectedRoster()
    {
        Map<Long, String> result = new LinkedHashMap<>();
        if (raid == null || !partyService.isInParty()) { return result; }
        List<String> names = new ArrayList<>(raid.names);
        if (raid.raid.equals("CoX"))
        {
            names.clear();
            for (PartyMember member : partyService.getMembers())
            {
                if (participating(member.getMemberId())) { names.add(RaidParty.name(member.getDisplayName())); }
            }
        }
        for (String name : names)
        {
            PartyMember match = null;
            for (PartyMember member : partyService.getMembers())
            {
                if (member.isLoggedIn() && name.equals(RaidParty.name(member.getDisplayName())))
                {
                    // Ambiguous display names are not safe identities.
                    if (match != null) { return new LinkedHashMap<>(); }
                    match = member;
                }
            }
            if (match != null && participating(match.getMemberId())) { result.put(match.getMemberId(), name); }
        }
        return result;
    }

    private boolean participating(long id)
    {
        if (raid == null) { return false; }
        if (id == localId()) { return true; }
        Presence peer = peers.get(id);
        return peer != null && peer.expires > System.currentTimeMillis() && raid.key().equals(peer.key);
    }

    private boolean isLeader(long id, Map<Long, String> roster)
    {
        if (raid == null || !roster.containsKey(id)) { return false; }
        if (!raid.raid.equals("CoX")) { return raid.leader().equals(roster.get(id)); }
        if (id == localId()) { return raid.localLeader; }
        Presence peer = peers.get(id);
        return participating(id) && peer.leader;
    }

    private long localId()
    {
        PartyMember local = partyService.getLocalMember();
        return local == null ? -1 : local.getMemberId();
    }

    private void refresh()
    {
        if (!running) { return; }
        raid = RaidParty.read(client);
        long now = System.currentTimeMillis();
        Map<Long, String> roster = connectedRoster();
        if (check != null)
        {
            if (raid == null || !raid.key().equals(checkRaidKey)
                || !roster.entrySet().containsAll(checkNames.entrySet()) || !isLeader(check.leader, roster))
            {
                check.cancel("Party changed - check cancelled", now);
            }
            check.tick(now);
        }
        boolean active = check != null && check.active();
        boolean leader = raid != null && raid.localLeader;
        boolean connected = roster.containsKey(localId());
        String status;
        if (raid == null) { status = "Ready checks are available in raid lobbies only"; }
        else if (!connected) { status = "Join a RuneLite party to connect plugin users"; }
        else { status = raid.raid + ": " + roster.size() + " plugin participant(s)"
            + (raid.raid.equals("CoX") ? (leader ? " - you lead" : " - waiting for raid leader")
                : " - leader: " + raid.leader()); }
        List<String> rows = new ArrayList<>();
        boolean visible = raid != null && check != null && check.visible(now);
        if (visible)
        {
            status = active ? "Ready up - " + Math.max(0, (check.deadline - now + 999) / 1000) + "s remaining" : check.result();
            checkNames.forEach((id, name) -> rows.add((check.ready.contains(id) ? "READY   " : active ? "WAITING " : "MISSED  ") + name));
        }
        else if (raid != null)
        {
            List<String> names = raid.raid.equals("CoX") ? new ArrayList<>(roster.values()) : raid.names;
            for (String name : names) { rows.add((roster.containsValue(name) ? "INCLUDED " : "SKIPPED  ") + name); }
        }
        view = new ReadyView(status, check == null ? null : check.id, rows,
            leader && connected && !active && now - lastStart >= 3000,
            active && check.members.contains(localId()) && !check.ready.contains(localId()), visible, active);
        ReadyView snapshot = view;
        SwingUtilities.invokeLater(() -> { if (running && panel != null) { panel.update(snapshot, leader); } });
    }

    void start(int seconds)
    {
        clientThread.invokeLater(() -> {
            refresh();
            if (!running || !view.canStart || seconds < 5 || seconds > 300) { return; }
            VisualReadyCheckMessage message = message("START", UUID.randomUUID().toString());
            message.startedAt = System.currentTimeMillis();
            message.durationSeconds = seconds;
            message.members = connectedRoster().keySet().stream().mapToLong(Long::longValue).toArray();
            partyService.send(message);
            receive(message, localId());
        });
    }

    // Called exclusively by a completed left click on the overlay's ready button.
    void ready(String checkId)
    {
        clientThread.invokeLater(() -> {
            refresh();
            if (!running || !view.canReady || check == null || !check.id.equals(checkId)) { return; }
            VisualReadyCheckMessage message = message("READY", checkId);
            partyService.send(message);
            receive(message, localId());
        });
    }

    void cancel()
    {
        clientThread.invokeLater(() -> {
            refresh();
            if (!running || check == null || !check.active() || check.leader != localId()) { return; }
            VisualReadyCheckMessage message = message("CANCEL", check.id);
            partyService.send(message);
            receive(message, localId());
        });
    }

    private VisualReadyCheckMessage message(String action, String id)
    {
        VisualReadyCheckMessage message = new VisualReadyCheckMessage();
        message.partyId = partyService.getPartyId();
        message.action = action;
        message.checkId = id;
        message.raidKey = raid == null ? null : raid.key();
        message.leader = raid != null && raid.localLeader;
        return message;
    }

    @Subscribe public void onVisualReadyCheckMessage(VisualReadyCheckMessage message)
    {
        clientThread.invokeLater(() -> receive(message, message.getMemberId()));
    }

    private void receive(VisualReadyCheckMessage message, long sender)
    {
        if (!running) { return; }
        refresh();
        if (!partyService.isInParty() || message.partyId != partyService.getPartyId()
            || partyService.getMemberById(sender) == null) { return; }
        if (message.version != 3)
        {
            diagnose(sender, "Different plugin version; all participants need the updated JAR");
            return;
        }
        long now = System.currentTimeMillis();
        if ("PRESENCE".equals(message.action) || "BYE".equals(message.action))
        {
            if (sender != localId())
            {
                diagnose(sender, message.raidKey == null ? "Plugin enabled, but no raid lobby detected"
                    : raid == null || !raid.key().equals(message.raidKey)
                        ? "Different lobby identity: local=" + (raid == null ? "none" : raid.key()) + "; remote=" + message.raidKey
                        : "Plugin discovered in the same raid lobby");
            }
            boolean fresh = !peers.containsKey(sender);
            if ("BYE".equals(message.action) || message.raidKey == null) { peers.remove(sender); }
            else if (message.raidKey.length() <= 2048)
            {
                peers.put(sender, new Presence(message.raidKey, message.leader, now));
                if (fresh && sender != localId()) { partyService.send(message("PRESENCE", null)); }
            }
            refresh();
            return;
        }
        if (raid == null || !raid.key().equals(message.raidKey) || message.checkId == null
            || message.checkId.length() > 36) { return; }
        if ("START".equals(message.action))
        {
            Map<Long, String> roster = connectedRoster();
            if (!isLeader(sender, roster) || message.members == null || message.members.length == 0
                || message.members.length > 100
                || message.durationSeconds < 5 || message.durationSeconds > 300
                || message.startedAt < now - 10000 || message.startedAt > now + 2000
                || message.startedAt + message.durationSeconds * 1000L <= now
                || seen.contains(message.checkId) || (check != null && check.active()) || now - lastStart < 3000) { return; }
            Set<Long> selected = new LinkedHashSet<>(Arrays.asList(Arrays.stream(message.members).boxed().toArray(Long[]::new)));
            if (selected.size() != message.members.length || !selected.contains(sender) || !selected.contains(localId())
                || !roster.keySet().containsAll(selected)) { return; }
            // The leader freezes participation at start. Later plugin discoveries join the next check.
            roster.keySet().retainAll(selected);
            seen.add(message.checkId);
            if (seen.size() > 128) { seen.remove(seen.iterator().next()); }
            lastStart = now;
            check = new ReadyCheck(message.checkId, sender, message.startedAt + message.durationSeconds * 1000L, roster.keySet());
            checkRaidKey = raid.key();
            checkNames.clear();
            checkNames.putAll(roster);
        }
        else if (check != null && check.id.equals(message.checkId))
        {
            if ("READY".equals(message.action)) { check.markReady(message.checkId, sender, now); }
            else if ("CANCEL".equals(message.action) && sender == check.leader) { check.cancel("Cancelled by leader", now); }
        }
        refresh();
    }

    private void diagnose(long sender, String reason)
    {
        if (!reason.equals(peerDiagnostics.put(sender, reason)))
        {
            PartyMember member = partyService.getMemberById(sender);
            log.info("Visual Ready Check discovery for {}: {}", member == null ? sender : member.getDisplayName(), reason);
        }
    }
}

package com.visualreadycheck;

import java.lang.reflect.Field;
import javax.swing.SwingUtilities;
import net.runelite.client.input.MouseManager;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.*;

public class PluginLifecycleTest
{
    private VisualReadyCheckPlugin plugin;
    private ClientToolbar toolbar;
    private WSClient transport;

    @Before public void setup() throws Exception
    {
        plugin = new VisualReadyCheckPlugin();
        toolbar = mock(ClientToolbar.class);
        transport = mock(WSClient.class);
        inject("toolbar", toolbar);
        inject("wsClient", transport);
        inject("partyService", mock(PartyService.class));
        inject("overlayManager", mock(OverlayManager.class));
        inject("mouseManager", mock(MouseManager.class));
        doAnswer(invocation -> {
            assertTrue("Panel must be created on Swing's event thread", SwingUtilities.isEventDispatchThread());
            return null;
        }).when(toolbar).addNavigation(any(NavigationButton.class));
    }

    private void inject(String name, Object value) throws Exception
    {
        Field field = VisualReadyCheckPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }

    @Test public void startsStopsAndReloadsOnEventThread() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            try
            {
                plugin.startUp();
                plugin.shutDown();
                plugin.startUp();
                plugin.shutDown();
            }
            catch (Exception exception) { throw new RuntimeException(exception); }
        });
        verify(toolbar, times(2)).addNavigation(any(NavigationButton.class));
        verify(toolbar, times(2)).removeNavigation(any(NavigationButton.class));
        verify(transport, times(2)).unregisterMessage(VisualReadyCheckMessage.class);
    }

    @Test public void startupFromWorkerWaitsForPanelCreation() throws Exception
    {
        plugin.startUp();
        verify(toolbar).addNavigation(any(NavigationButton.class));
        SwingUtilities.invokeAndWait(plugin::shutDown);
    }
}

package com.visualreadycheck;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ProtocolTest
{
    private VisualReadyCheckPlugin plugin;
    private Client client;
    private PartyService service;

    @Before public void setup() throws Exception
    {
        plugin = new VisualReadyCheckPlugin();
        client = mock(Client.class);
        service = mock(PartyService.class);
        Player player = mock(Player.class);
        when(player.getName()).thenReturn("Member");
        when(client.getLocalPlayer()).thenReturn(player);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getWidget(InterfaceID.TobHud.NAMES)).thenReturn(mock(Widget.class));
        when(client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS)).thenReturn(1);
        when(client.getWidget(InterfaceID.TobHud.NAMES).getText()).thenReturn("Leader<br>Member");
        PartyMember leader = member(1L, "Leader");
        PartyMember local = member(2L, "Member");
        PartyMember outsider = member(3L, "Outsider");
        when(service.getMembers()).thenReturn(Arrays.asList(leader, local, outsider));
        when(service.getLocalMember()).thenReturn(local);
        when(service.getMemberById(1L)).thenReturn(leader);
        when(service.getMemberById(2L)).thenReturn(local);
        when(service.getMemberById(3L)).thenReturn(outsider);
        when(service.isInParty()).thenReturn(true);
        when(service.getPartyId()).thenReturn(99L);
        set("client", client);
        set("partyService", service);
        set("running", true);
        VisualReadyCheckMessage presence = start();
        presence.action = "PRESENCE";
        presence.leader = true;
        receive(presence, 1L);
    }

    private PartyMember member(long id, String name)
    {
        PartyMember member = mock(PartyMember.class);
        when(member.getMemberId()).thenReturn(id);
        when(member.getDisplayName()).thenReturn(name);
        when(member.isLoggedIn()).thenReturn(true);
        return member;
    }

    private void set(String field, Object value) throws Exception
    {
        Field f = VisualReadyCheckPlugin.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(plugin, value);
    }

    private void receive(VisualReadyCheckMessage message, long sender) throws Exception
    {
        Method method = VisualReadyCheckPlugin.class.getDeclaredMethod("receive", VisualReadyCheckMessage.class, long.class);
        method.setAccessible(true);
        method.invoke(plugin, message, sender);
    }

    private VisualReadyCheckMessage start()
    {
        VisualReadyCheckMessage message = new VisualReadyCheckMessage();
        message.action = "START";
        message.partyId = 99L;
        message.raidKey = RaidParty.read(client).key();
        message.checkId = "test-check";
        message.durationSeconds = 30;
        message.startedAt = System.currentTimeMillis();
        message.members = new long[]{1L, 2L};
        return message;
    }

    @Test public void onlyGameLeaderCanStartAndOutsidersAreExcluded() throws Exception
    {
        receive(start(), 2L);
        assertFalse(plugin.view().active);
        receive(start(), 3L);
        assertFalse(plugin.view().active);
        receive(start(), 1L);
        assertTrue(plugin.view().active);
        assertEquals(2, plugin.view().rows.size());
        assertTrue(plugin.view().canReady);
