package com.visualreadycheck;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class RaidPartyTest
{
    private Client client()
    {
        Client client = mock(Client.class);
        Player player = mock(Player.class);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getLocalPlayer()).thenReturn(player);
        when(player.getName()).thenReturn("Member");
        when(client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER)).thenReturn(-1);
        when(client.getWidget(InterfaceID.TobHud.NAMES)).thenReturn(mock(Widget.class));
        when(client.getWidget(InterfaceID.ToaLobby.NAMES)).thenReturn(mock(Widget.class));
        when(client.getWidget(InterfaceID.TfaLobby.NAMES)).thenReturn(mock(Widget.class));
        return client;
    }

    @Test public void readsAllThreeLobbyRosters()
    {
        int[] statuses = {VarbitID.TOB_CLIENT_PARTYSTATUS, VarbitID.TOA_CLIENT_PARTYSTATUS, VarbitID.TFA_CLIENT_PARTYSTATUS};
        int[] names = {InterfaceID.TobHud.NAMES, InterfaceID.ToaLobby.NAMES, InterfaceID.TfaLobby.NAMES};
        String[] raids = {"ToB", "ToA", "TFA"};
        for (int i = 0; i < statuses.length; i++)
        {
            Client client = client();
            when(client.getVarbitValue(statuses[i])).thenReturn(1);
            when(client.getWidget(names[i]).getText()).thenReturn("<col=ffffff>Leader</col><br>Member");
            RaidParty party = RaidParty.read(client);
            assertNotNull(party);
            assertEquals(raids[i], party.raid);
            assertEquals("leader", party.leader());
            assertEquals(2, party.names.size());
        }
    }

    @Test public void rejectsStaleRosterAndLeaderlessParty()
    {
        Client client = client();
        when(client.getWidget(InterfaceID.TobHud.NAMES).getText()).thenReturn("Leader<br>Member");
        assertNull(RaidParty.read(client));
        when(client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS)).thenReturn(1);
        when(client.getWidget(InterfaceID.TobHud.NAMES).getText()).thenReturn("<br>Member");
        assertNull(RaidParty.read(client));
    }

    @Test public void spectatorCannotUseOtherPeoplesRoster()
    {
        Client client = client();
        when(client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS)).thenReturn(2);
        when(client.getWidget(InterfaceID.TobHud.NAMES).getText()).thenReturn("Someone else");
        assertNull(RaidParty.read(client));
    }

    @Test public void coxWorksWithoutOpeningAnyTabAndStopsWhenRaidStarts()
    {
        Client client = client();
        when(client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER)).thenReturn(42);
        when(client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON)).thenReturn(1);
        when(client.getVarbitValue(VarbitID.RAIDS_CLIENT_ISLEADER)).thenReturn(1);
        assertTrue(RaidParty.read(client).localLeader);
        assertEquals("CoX", RaidParty.read(client).raid);
        verify(client, never()).getWidget(500, 10);
        when(client.getVarbitValue(VarbitID.RAIDS_CLIENT_PROGRESS)).thenReturn(1);
        assertNull(RaidParty.read(client));
    }

    @Test public void staleNamesOutsideLobbyDoNotEnableChecks()
    {
        Client client = client();
        when(client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS)).thenReturn(2);
        when(client.getWidget(InterfaceID.TobHud.NAMES).getText()).thenReturn("Member");
        when(client.getWidget(InterfaceID.TobHud.NAMES).isHidden()).thenReturn(true);
        assertNull(RaidParty.read(client));
    }

    @Test public void tfaLobbyOverridesPreviousRaidsStaleNames()
    {
        Client client = client();
        when(client.getLocalPlayer().getName()).thenReturn("LogicalHash");
        when(client.getVarbitValue(VarbitID.TFA_CLIENT_PARTYSTATUS)).thenReturn(1);
        when(client.getVarcStrValue(VarClientID.TFA_CLIENT_NAME0)).thenReturn("originaltc");
        when(client.getVarcStrValue(VarClientID.TFA_CLIENT_NAME1)).thenReturn("ivar bonez");
        when(client.getVarcStrValue(VarClientID.TFA_CLIENT_NAME2)).thenReturn("LogicalHash");
        when(client.getWidget(InterfaceID.TfaLobby.NAMES).getText()).thenReturn("LogicalHash<br>This Whip<br>Godly");
        RaidParty party = RaidParty.read(client);
        assertTrue(party.localLeader);
        assertEquals(java.util.Arrays.asList("logicalhash", "this whip", "godly"), party.names);
        when(client.getWidget(InterfaceID.TfaLobby.NAMES).getText()).thenReturn("This Whip<br>LogicalHash<br>Godly");
        assertFalse(RaidParty.read(client).localLeader);
    }

    @Test public void tfaEmptySlotMarkersDoNotChangeSharedPartyIdentity()
    {
        Client first = client();
        Client second = client();
        when(first.getLocalPlayer().getName()).thenReturn("LogicalHash");
        when(second.getLocalPlayer().getName()).thenReturn("Mr Swann");
        for (Client client : new Client[]{first, second})
        {
            when(client.getWorld()).thenReturn(614);
            when(client.getVarbitValue(VarbitID.TFA_CLIENT_PARTYSTATUS)).thenReturn(1);
        }
        when(first.getWidget(InterfaceID.TfaLobby.NAMES).getText()).thenReturn("LogicalHash<br>Mr Swann");
        when(second.getWidget(InterfaceID.TfaLobby.NAMES).getText())
            .thenReturn("LogicalHash<br>Mr Swann<br><col=aaaaaa> - </col><br>-<br>");
        assertEquals("TFA:614:logicalhash:logicalhash,mr swann", RaidParty.read(second).key());
        assertEquals(RaidParty.read(first).key(), RaidParty.read(second).key());
        assertEquals(2, RaidParty.read(second).names.size());
        assertTrue(RaidParty.read(first).localLeader);
        assertFalse(RaidParty.read(second).localLeader);
        when(second.getWidget(InterfaceID.TfaLobby.NAMES).getText()).thenReturn("-<br>Mr Swann");
        assertNull("An empty leader slot must not promote the next member", RaidParty.read(second));
    }

    @Test public void normalizesGameAndTransportNames()
    {
        assertEquals("a b c", RaidParty.name("<img=1>A_B\u00a0C"));
    }

    @Test public void lobbyIdentityIsSharedAcrossControllersAndMemberDisplayOrder()
    {
        RaidParty first = new RaidParty("TFA", 123, java.util.Arrays.asList("leader", "alice", "bob"));
        RaidParty second = new RaidParty("TFA", -1, java.util.Arrays.asList("leader", "bob", "alice"));
        assertEquals(first.key(), second.key());
        assertNotEquals(first.key(), new RaidParty("TFA", 123, java.util.Arrays.asList("alice", "leader", "bob")).key());
        assertNotEquals(first.key(), new RaidParty("TFA", 123, java.util.Arrays.asList("leader", "alice", "outsider")).key());
    }
}

package com.visualreadycheck;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public class ReadyCheckTest
{
    private ReadyCheck check() { return new ReadyCheck("current", 1L, 10000, Arrays.asList(1L, 2L)); }

    @Test public void leaderMustClickToo()
    {
        ReadyCheck check = check();
        assertTrue(check.ready.isEmpty());
        assertTrue(check.markReady("current", 2L, 1000));
        assertTrue(check.active());
        assertTrue(check.markReady("current", 1L, 2000));
        assertFalse(check.active());
        assertEquals("Everyone is ready!", check.result());
    }

    @Test public void ignoresOldChecksOutsidersAndDuplicates()
    {
        ReadyCheck check = check();
        assertFalse(check.markReady("previous", 1L, 1000));
        assertFalse(check.markReady("current", 3L, 1000));
        assertTrue(check.markReady("current", 1L, 1000));
        assertFalse(check.markReady("current", 1L, 1000));
        assertEquals(1, check.ready.size());
    }

    @Test public void clickAtDeadlineCannotTurnTimeoutIntoSuccess()
    {
        ReadyCheck check = check();
        check.markReady("current", 1L, 9000);
        assertFalse(check.markReady("current", 2L, 10000));
        assertEquals("Time expired", check.result());
        assertTrue(check.visible(17999));
        assertFalse(check.visible(18000));
    }

    @Test public void cancellationIsTerminal()
    {
        ReadyCheck check = check();
        check.cancel("Party changed", 1000);
        assertFalse(check.markReady("current", 1L, 2000));
        check.tick(11000);
        assertEquals("Party changed", check.result());
    }
}

package com.visualreadycheck;

import java.awt.Canvas;
import java.awt.Graphics2D;
import java.awt.event.InputEvent;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ReadyOverlayTest
{
    private VisualReadyCheckPlugin plugin;
    private ReadyOverlay overlay;
    private final Canvas canvas = new Canvas();

    @Before public void setup()
    {
        plugin = mock(VisualReadyCheckPlugin.class);
        when(plugin.config()).thenReturn(new VisualReadyCheckConfig() {});
        when(plugin.view()).thenReturn(new ReadyView("Ready up", "id", Arrays.asList("WAITING You"), false, true, true, true));
        overlay = new ReadyOverlay(plugin);
        overlay.getBounds().setLocation(100, 100);
        Graphics2D g = new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB).createGraphics();
        overlay.render(g);
        g.dispose();
    }

    private MouseEvent event(int kind, int x, int y, int modifiers)
    {
        return new MouseEvent(canvas, kind, 0, modifiers, x, y, 1, false, MouseEvent.BUTTON1);
    }

    @Test public void completedLeftClickConfirmsAndIsConsumed()
    {
        MouseEvent press = event(MouseEvent.MOUSE_PRESSED, 130, 210, 0);
        MouseEvent release = event(MouseEvent.MOUSE_RELEASED, 130, 210, 0);
        overlay.mouse.mousePressed(press);
        overlay.mouse.mouseReleased(release);
        verify(plugin).ready("id");
        assertTrue(press.isConsumed());
        assertTrue(release.isConsumed());
    }

    @Test public void altDraggingAndDraggingAwayNeverConfirm()
    {
        overlay.mouse.mousePressed(event(MouseEvent.MOUSE_PRESSED, 130, 210, InputEvent.ALT_DOWN_MASK));
        overlay.mouse.mouseReleased(event(MouseEvent.MOUSE_RELEASED, 130, 210, 0));
        overlay.mouse.mousePressed(event(MouseEvent.MOUSE_PRESSED, 130, 210, 0));
        overlay.mouse.mouseDragged(event(MouseEvent.MOUSE_DRAGGED, 140, 210, 0));
        overlay.mouse.mouseReleased(event(MouseEvent.MOUSE_RELEASED, 130, 210, 0));
        verify(plugin, never()).ready(any());
    }

    @Test public void releaseWithoutPressNeverConfirms()
    {
        overlay.mouse.mouseReleased(event(MouseEvent.MOUSE_RELEASED, 130, 210, 0));
        verify(plugin, never()).ready(any());
    }

    @Test public void sizeChangesScaleDrawingAndClickTargetTogether()
    {
        for (int percent : new int[]{75, 125, 200})
        {
            clearInvocations(plugin);
            when(plugin.config()).thenReturn(new VisualReadyCheckConfig() {
                @Override public int overlayScale() { return percent; }
            });
            Graphics2D g = new BufferedImage(600, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();
            java.awt.Dimension size = overlay.render(g);
            g.dispose();
            double scale = percent / 100.0;
            assertEquals((int) Math.ceil(248 * scale), size.width);
            assertEquals((int) Math.ceil(140 * scale), size.height);
            // Outside the left edge of the button must never confirm.
            int y = 100 + (int) (110 * scale);
            overlay.mouse.mousePressed(event(MouseEvent.MOUSE_PRESSED, 102, y, 0));
            overlay.mouse.mouseReleased(event(MouseEvent.MOUSE_RELEASED, 102, y, 0));
            verify(plugin, never()).ready(any());
            int x = 100 + (int) (30 * scale);
            overlay.mouse.mousePressed(event(MouseEvent.MOUSE_PRESSED, x, y, 0));
            overlay.mouse.mouseReleased(event(MouseEvent.MOUSE_RELEASED, x, y, 0));
            verify(plugin).ready("id");
        }
    }

    @Test public void nativeResizeScalesButtonAndResetRestoresConfiguredSize()
    {
        assertTrue(overlay.isResizable());
        overlay.setPreferredSize(new java.awt.Dimension(496, 280));
        Graphics2D g = new BufferedImage(600, 500, BufferedImage.TYPE_INT_ARGB).createGraphics();
        assertEquals(new java.awt.Dimension(496, 280), overlay.render(g));
        overlay.mouse.mousePressed(event(MouseEvent.MOUSE_PRESSED, 160, 320, InputEvent.ALT_DOWN_MASK));
        overlay.mouse.mouseReleased(event(MouseEvent.MOUSE_RELEASED, 160, 320, 0));
        verify(plugin, never()).ready(any());
        overlay.mouse.mousePressed(event(MouseEvent.MOUSE_PRESSED, 160, 320, 0));
        overlay.mouse.mouseReleased(event(MouseEvent.MOUSE_RELEASED, 160, 320, 0));
        verify(plugin).ready("id");
        overlay.setPreferredSize(null);
        assertEquals(new java.awt.Dimension(248, 140), overlay.render(g));
        g.dispose();
    }
}

package com.visualreadycheck;

import java.awt.Component;
import java.awt.Container;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.util.Arrays;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

public class ReadyPanelLayoutTest
{
    @Test public void topCardUsesFullWidthAtSidebarSize() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            try
            {
                ReadyPanel panel = new ReadyPanel(new VisualReadyCheckPlugin());
                panel.update(new ReadyView("TFA: 1 plugin participant(s) - leader: godly", null,
                    Arrays.asList("SKIPPED godly", "INCLUDED logicalhash", "SKIPPED c h i v e s", "SKIPPED this whip"),
                    false, false, false, false), false);
                panel.setSize(244, 740);
                for (int i = 0; i < 4; i++) { layout(panel); }
                Component status = field(panel, "status");
                Component start = field(panel, "start");
                Component role = field(panel, "role");
                assertEquals(role.getX(), status.getX());
                assertEquals(status.getX(), start.getX());
                assertEquals(status.getWidth(), start.getWidth());
                assertTrue("Status must not collapse to a narrow column", status.getWidth() >= 180);
                assertTrue("Start button must remain compact", start.getHeight() <= 36);
                BufferedImage image = new BufferedImage(244, 740, BufferedImage.TYPE_INT_RGB);
                java.awt.Graphics2D graphics = image.createGraphics();
                panel.printAll(graphics);
                graphics.dispose();
                javax.imageio.ImageIO.write(image, "png", new java.io.File("build/panel-layout.png"));
            }
            catch (Exception exception) { throw new RuntimeException(exception); }
        });
    }

    private static Component field(ReadyPanel panel, String name) throws Exception
    {
        Field field = ReadyPanel.class.getDeclaredField(name);
        field.setAccessible(true);
        return (Component) field.get(panel);
    }

    private static void layout(Container container)
    {
        container.doLayout();
        for (Component child : container.getComponents())
        {
            if (child instanceof Container) { layout((Container) child); }
        }
    }
}

